<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { fetchPublicAbout, type PublicAbout } from '@/api/about'
import MarkdownRenderer from '@/components/MarkdownRenderer.vue'
import TechFlow from '@/components/about/TechFlow.vue'
import CareerSnapshot from '@/components/about/CareerSnapshot.vue'
import EvidenceGrid from '@/components/about/EvidenceGrid.vue'
const about=ref<PublicAbout|null>(null);const loading=ref(true);const error=ref(false)
const sections=computed(()=>[{id:'focus',label:'此刻',visible:!!about.value?.currentFocus.length},{id:'direction',label:'技术地图',visible:!!about.value?.technicalDirectionMarkdown},{id:'journey',label:'学习经历',visible:!!about.value?.journeyMarkdown},{id:'selected',label:'精选成果',visible:!!(about.value?.selectedProjects.length||about.value?.selectedTutorials.length||about.value?.selectedBlogs.length)},{id:'contact',label:'保持联系',visible:!!(about.value?.publicEmail||about.value?.githubUrl||about.value?.resumeUrl)}].filter(item=>item.visible))
const initials=computed(()=>about.value?.displayName?.slice(0,1)||'星')
const career=computed(()=>({headline:about.value?.headline??null,focus:about.value?.currentFocus??[],featured:about.value?.selectedProjects?.[0]?.title??'星雨笔录',status:'持续学习与构建中'}))
const evidence=computed(()=>[...(about.value?.selectedProjects??[]).map(p=>({title:p.title,to:`/portfolio/${p.slug}`,note:'工程实践项目',kind:'PROJECT'})),...(about.value?.selectedTutorials??[]).map(t=>({title:t.title,to:`/tutorials/${t.slug}`,note:'成体系的教程',kind:'KNOWLEDGE'})),...(about.value?.selectedBlogs??[]).map(b=>({title:b.title,to:`/blog/${b.slug}`,note:'实践记录与思考',kind:'WRITING'}))])
onMounted(async()=>{try{about.value=await fetchPublicAbout()}catch{error.value=true}finally{loading.value=false}})
</script>
